!function(){"use strict";document.addEventListener("click",function(e){var t=e.target.closest(".notran-fee-add");if(t){var r=t.closest(".notran-fees"),n=r.querySelector(".notran-fee-rows");if(n.children.length>=20)return;var a=Number(r.dataset.next)||0;n.insertAdjacentHTML("beforeend",r.querySelector("template").innerHTML.replace(/__ROW__/g,String(a))),r.dataset.next=a+1,n.lastElementChild.querySelector("input").focus()}var o=e.target.closest(".notran-fee-remove");o&&o.closest(".notran-fee-row").remove()})}();